        "sourceMetadata": {
          "internalAbilityName": "broodmother_spawn_spiderlings",
          "officialDisplayName": "Spawn Spiderlings",
          "officialDescription": "Broodmother injects her young into an enemy unit, dealing damage and slowing them for %slow_duration% seconds. The spiderlings will hatch if the target is killed while under this influence.",
          "notes": [
            "If the target is killed within %buff_duration% seconds of being hit with this skill, the Spiderlings will spawn.",
            "Units killed by Spiderlings will then give birth to additional Spiderlings."
          ]
        }
