        "sourceMetadata": {
          "internalAbilityName": "windrunner_shackleshot",
          "officialDisplayName": "Shackleshot",
          "officialDescription": "Shackles the target to an enemy unit or tree in a line directly behind it.  If no unit or tree is present, the stun duration is reduced to %fail_stun_duration%.",
          "notes": [
            "This spell can shackle two enemies together, stunning them both.",
            "Can shackle the target to an enemy unit or tree at most %shackle_distance% behind the target.",
            "Shackleshot can be disjointed."
          ]
        }
